fn solve(word: Vec<char>) -> Vec<char> {
    // Define sets A and B as arrays of chars for quick membership checking
    const SET_A: [char; 15] = ['A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z'];
    const SET_B: [char; 11] = ['B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U'];

    // Helper closures to check membership
    let in_a = |c: char| SET_A.contains(&c);
    let in_b = |c: char| SET_B.contains(&c);

    // Return "NO" early if empty input (though problem states length 1..=10)
    if word.is_empty() {
        return "NO".chars().collect();
    }

    // Determine the set of the first character
    let first_char = word[0];
    let first_in_a = in_a(first_char);
    let first_in_b = in_b(first_char);

    // If first char is not in either set, return "NO"
    if !first_in_a && !first_in_b {
        return "NO".chars().collect();
    }

    // Check if all chars belong to the same set as the first char
    let all_in_same_set = if first_in_a {
        word.iter().all(|&c| in_a(c))
    } else {
        word.iter().all(|&c| in_b(c))
    };

    if all_in_same_set {
        "YES".chars().collect()
    } else {
        "NO".chars().collect()
    }
}